using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class PlaceRequestChecks {
 static void Require(bool value,string why){if(!value)throw new Exception(why);}
 public static void VerifyModel(){
  var place=new GatheringPlaceMemory();Require(!place.Ask(0),"Unknown experience requested improvement");place.visits=1;Require(place.Ask(0)&&!place.Ask(1)&&place.requests==1&&place.Ask(180),"Request cooldown failed");
  var m=new SocialMemory{gatheringPlaces=new[]{place}};Require(JsonUtility.FromJson<SocialMemory>(JsonUtility.ToJson(m)).Valid()&&JsonUtility.FromJson<SocialMemory>("{}").Valid(),"Request save/legacy invalid");place.answers=3;Require(!m.Valid(),"Invented answers accepted");place.answers=1;place.coverUses=1;place.ballUses=1;Require(!m.Valid(),"More completed uses than accepted requests allowed");place.ballUses=0;Require(m.Valid(),"Bounded confirmed use rejected");place.coverUses=-1;Require(!m.Valid(),"Negative use count accepted");place.coverUses=0;place.answers=0;place.nextRequestAt=float.NaN;Require(!m.Valid(),"Invalid request timer accepted");Debug.Log("BWVR_PLACE_REQUEST_MODEL_PASS");
 }
 public static void VerifyRuntime()=>VerifyWithCapture(null);
 public static void VerifyWithCapture(Action<VillagerExploration,PlaceImprovement> capture){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var people=slice.GetComponentsInChildren<VillagerExploration>();var actor=people[0];var nav=actor.GetComponent<IslandNavigator>();var ball=slice.GetComponentInChildren<BeachBall>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=field.GetValue(slice);var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var records=site.Capture();var recipe=site.Recipe;bool sitePaused=site.Paused;var ballHome=ball.GetComponent<CarryItem>().home;var ballAt=ball.transform.position;var ballRotation=ball.transform.rotation;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};test.Hybrid.time=200;god.Interrupt("Place requests QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerSocial>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();}field.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();var memory=test.Social(0);var hands=actor.GetComponentInChildren<HumanoidHands>();
  void Stage(){actor.ResetTask();Require(nav.world.Sample(site.World(new Vector3(0,0,-11)),nav.profile,8,out var at),"No request approach");actor.transform.position=nav.world.ProjectFoot(at,nav.profile);nav.ResetRoute();}
  void Step(){test.Hybrid.time+=.05f;actor.Tick(.05f,false);}
  void Show(){for(int i=0;i<1600&&actor.GatheringRequest==PlaceImprovement.None&&actor.Active;i++)Step();Require(actor.GatheringRequest!=PlaceImprovement.None,"Native request approach failed");Step();}
  void PutBall(Vector3 at){ball.GetComponent<CarryItem>().held=false;ball.transform.position=at;ball.Body.position=nav.world.ToNav(at);ball.Body.linearVelocity=ball.Body.angularVelocity=Vector3.zero;Physics.SyncTransforms();}
  try{
   site.Paused=false;site.ResetConstruction();Stage();test.Weather.rain=1;memory.restNeed=.95f;Require(!actor.TryPlaceImprovement(site),"Villager invented prior experience");memory.RememberPlace(0,false,0);
   actor.Tick(120,false);Require(actor.Current==VillagerExploration.Phase.PlaceRequest,"Native leisure selection did not offer cover request");Show();var place=memory.Place(0);capture?.Invoke(actor,PlaceImprovement.Cover);Require(place.requests==1&&hands.sheltering&&hands.resource==null&&!actor.GetComponent<VillagerRoutine>().bucket.gameObject.activeSelf&&site.Requester==actor,"Cover gesture or request lease missing");
   Require(!people[1].TryPlaceImprovement(site),"Second requester stole place");actor.Tick(20,true);Require(actor.GatheringRequest==PlaceImprovement.Cover&&place.answers==0,"Pause advanced request");actor.GetComponent<CarryItem>().held=true;actor.Tick(.1f,false);actor.GetComponent<CarryItem>().held=false;Require(site.Requester==null&&!hands.sheltering&&place.answers==0,"Pickup retained pose/lease or invented answer");Require(!actor.TryPlaceImprovement(site),"Request cooldown bypassed");
   place.nextRequestAt=0;Stage();Require(actor.TryPlaceImprovement(site),"Cover restart failed");Show();test.Weather.rain=0;Step();Require(site.Requester==null&&place.answers==0,"Weather clearing falsely answered request");
   test.Weather.rain=1;place.nextRequestAt=0;Stage();Require(actor.TryPlaceImprovement(site),"Cover third start failed");Show();
   ConstructionBlock Put(ConstructionShape shape,Vector3 at){var b=site.blocks.First(b=>b.Shape==shape&&!b.Attached);Require(site.Drop(b,site.World(at),site.transform.rotation),"Canopy staging failed");return b;}
   Put(ConstructionShape.Column,new Vector3(-2,2.4f,-12));Put(ConstructionShape.Column,new Vector3(2,2.4f,-12));var roof=Put(ConstructionShape.Slab,new Vector3(0,5.4f,-12));for(int i=0;i<10&&place.answers==0;i++)Step();Require(place.answers==1&&site.Requester==null&&site.Visitor==actor&&!hands.sheltering,"Real cover did not hand off to shelter use");
   Require(place.coverUses==0&&place.ballUses==0,"Handoff falsely credited completed use");actor.Tick(10,true);Require(place.coverUses==0,"Paused rest completed request");
   var pendingSave=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(pendingSave.Valid()&&pendingSave.Social(0).Place(0).coverUses==0,"Save fabricated pending completion");
   site.ReturnLoose(roof);Step();Require(site.Visitor==null&&place.coverUses==0,"Lost roof credited completion or kept visitor");
   Require(site.Drop(roof,site.World(new Vector3(0,5.4f,-12)),site.transform.rotation),"Restore canceled roof failed");Stage();Require(actor.TryShelter(site),"Ordinary rest staging failed");for(int i=0;i<3000&&memory.shelterRests==0;i++)Step();Require(memory.shelterRests==1&&place.coverUses==0,"Later unrelated rest completed canceled request");
   actor.ResetTask();site.ReturnLoose(roof);place.nextRequestAt=0;memory.restNeed=.95f;Stage();Require(actor.TryPlaceImprovement(site),"Second cover request rejected");Show();Require(site.Drop(roof,site.World(new Vector3(0,5.4f,-12)),site.transform.rotation),"Second canopy staging failed");for(int i=0;i<10&&place.answers<2;i++)Step();Require(place.answers==2&&place.coverUses==0,"Second handoff invalid");for(int i=0;i<3000&&memory.shelterRests<2;i++)Step();Require(memory.shelterRests==2&&place.coverUses==1,"Completed requested cover did not supply actual rest/receipt");
   for(int i=0;i<10;i++)Step();Require(place.coverUses==1,"Repeated completion credited twice");
   actor.ResetTask();place.nextRequestAt=0;memory.restNeed=.95f;Require(!actor.TryPlaceImprovement(site),"Villager requested cover that is already usable");site.ResetConstruction();test.Weather.rain=0;place.appeal=.8f;place.nextRequestAt=0;memory.restNeed=.5f;memory.ballGames=0;ball.ReturnHome();ball.GetComponent<CreatureAffordance>().cooldown=0;Stage();
   bool started=false;for(int i=0;i<16&&!started;i++){var dir=Quaternion.Euler(0,i*22.5f,0)*Vector3.forward;var desired=site.transform.position+dir*nav.world.Scale*34;if(!nav.world.Sample(desired,nav.profile,3,out var at))continue;at=nav.world.ProjectFoot(at,nav.profile)+Vector3.up*nav.world.Scale*ball.Radius;PutBall(at);actor.transform.LookAt(new Vector3(at.x,actor.transform.position.y,at.z));Require(!actor.TryPlaceImprovement(site),"Villager requested an unfamiliar toy");memory.ballGames=1;started=actor.TryPlaceImprovement(site);memory.ballGames=0;}Require(started,"Familiar visible ball did not produce request");memory.ballGames=1;Show();actor.Tick(2.5f,false);capture?.Invoke(actor,PlaceImprovement.BeachBall);Require(actor.GatheringRequest==PlaceImprovement.BeachBall,"Wrong toy request");int answers=place.answers;
   ball.GetComponent<CarryItem>().held=true;ball.transform.position=site.World(new Vector3(0,ball.Radius,-16));actor.Tick(.3f,false);Require(place.answers==answers&&actor.GatheringRequest==PlaceImprovement.BeachBall,"Player-held delivery treated as available toy");PutBall(site.World(new Vector3(0,ball.Radius,-16)));actor.Tick(.3f,false);Require(place.answers==answers+1&&ball.Player==actor&&site.Requester==null,"Released ball did not hand off to native play");
   actor.ResetTask();Require(place.ballUses==0&&place.coverUses==1,"Canceled ball handoff gained use credit");ball.ReturnHome();place.nextRequestAt=0;memory.restNeed=.95f;test.Weather.rain=1;Stage();Require(actor.TryPlaceImprovement(site),"Timeout request rejected");Show();answers=place.answers;for(int i=0;i<400&&actor.Current==VillagerExploration.Phase.PlaceRequest;i++)Step();Require(site.Requester==null&&place.answers==answers&&!hands.sheltering,"Expired request retained ownership or reward");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.Social(0).Place(0).answers==3&&saved.Social(0).Place(0).coverUses==1&&saved.Social(0).Place(0).ballUses==0&&saved.Social(0).Place(0).requests==place.requests,"Request history save invalid");Debug.Log("BWVR_PLACE_REQUEST_RUNTIME_PASS: evidence gates, native approach, overhead gesture, exclusivity, pause/pickup, cooldown/weather/timeout cleanup, real roof and released ball handoffs, persistence");
  }finally{actor.GetComponent<CarryItem>().held=false;actor.ResetTask();ball.GetComponent<CarryItem>().held=false;ball.CancelRally();site.Recipe=recipe;site.Restore(records);site.Paused=sitePaused;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}field.SetValue(slice,original);ball.GetComponent<CarryItem>().home=ballHome;ball.ResetWorld();ball.transform.SetPositionAndRotation(ballAt,ballRotation);ball.Body.position=nav.world.ToNav(ballAt);}
 }
}
}
